253|size_t ZSTD_CCtx_setParameter(ZSTD_CCtx* cctx, ZSTD_cParameter param, unsigned value)
254|{
255|    if (cctx->streamStage != zcss_init) return ERROR(stage_wrong);
256|
257|    switch(param)
258|    {
259|    case ZSTD_p_format :
260|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
261|
262|    case ZSTD_p_compressionLevel:
263|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
264|        if (cctx->cdict) return ERROR(stage_wrong);
265|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
266|
267|    case ZSTD_p_windowLog:
268|    case ZSTD_p_hashLog:
269|    case ZSTD_p_chainLog:
270|    case ZSTD_p_searchLog:
271|    case ZSTD_p_minMatch:
272|    case ZSTD_p_targetLength:
273|    case ZSTD_p_compressionStrategy:
274|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
275|        if (cctx->cdict) return ERROR(stage_wrong);
276|        ZSTD_cLevelToCParams(cctx);  /* Can optimize if srcSize is known */
277|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
278|
279|    case ZSTD_p_contentSizeFlag:
280|    case ZSTD_p_checksumFlag:
281|    case ZSTD_p_dictIDFlag:
282|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
283|
284|    case ZSTD_p_forceMaxWindow :  /* Force back-references to remain < windowSize,
285|                                   * even when referencing into Dictionary content
286|                                   * default : 0 when using a CDict, 1 when using a Prefix */
287|        cctx->loadedDictEnd = 0;
288|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
289|
290|    case ZSTD_p_nbThreads:
291|        if (value==0) return 0;
292|        DEBUGLOG(5, " setting nbThreads : %u", value);
293|        if (value > 1 && cctx->staticSize) {
294|            return ERROR(parameter_unsupported);  /* MT not compatible with static alloc */
295|        }
296|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
297|
298|    case ZSTD_p_jobSize:
299|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
300|
301|    case ZSTD_p_overlapSizeLog:
302|        DEBUGLOG(5, " setting overlap with nbThreads == %u", cctx->requestedParams.nbThreads);
303|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
304|
305|    case ZSTD_p_enableLongDistanceMatching:
306|        if (cctx->cdict) return ERROR(stage_wrong);
307|        if (value != 0) {
308|            ZSTD_cLevelToCParams(cctx);
309|        }
310|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
311|
312|    case ZSTD_p_ldmHashLog:
313|    case ZSTD_p_ldmMinMatch:
314|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
315|        if (cctx->cdict) return ERROR(stage_wrong);
316|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
317|
318|    case ZSTD_p_ldmBucketSizeLog:
319|    case ZSTD_p_ldmHashEveryLog:
320|        if (cctx->cdict) return ERROR(stage_wrong);
321|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
322|
323|    default: return ERROR(parameter_unsupported);
324|    }
325|}

327|size_t ZSTD_CCtxParam_setParameter(
328|        ZSTD_CCtx_params* params, ZSTD_cParameter param, unsigned value)
329|{
330|    switch(param)
331|    {
332|    case ZSTD_p_format :
333|        if (value > (unsigned)ZSTD_f_zstd1_magicless)
334|            return ERROR(parameter_unsupported);
335|        params->format = (ZSTD_format_e)value;
336|        return 0;
337|
338|    case ZSTD_p_compressionLevel :
339|        if ((int)value > ZSTD_maxCLevel()) value = ZSTD_maxCLevel();
340|        if (value == 0) return 0;
341|        params->compressionLevel = value;
342|        return 0;
343|
344|    case ZSTD_p_windowLog :
345|        if (value == 0) return 0;
346|        CLAMPCHECK(value, ZSTD_WINDOWLOG_MIN, ZSTD_WINDOWLOG_MAX);
347|        ZSTD_cLevelToCCtxParams(params);
348|        params->cParams.windowLog = value;
349|        return 0;
350|
351|    case ZSTD_p_hashLog :
352|        if (value == 0) return 0;
353|        CLAMPCHECK(value, ZSTD_HASHLOG_MIN, ZSTD_HASHLOG_MAX);
354|        ZSTD_cLevelToCCtxParams(params);
355|        params->cParams.hashLog = value;
356|        return 0;
357|
358|    case ZSTD_p_chainLog :
359|        if (value == 0) return 0;
360|        CLAMPCHECK(value, ZSTD_CHAINLOG_MIN, ZSTD_CHAINLOG_MAX);
361|        ZSTD_cLevelToCCtxParams(params);
362|        params->cParams.chainLog = value;
363|        return 0;
364|
365|    case ZSTD_p_searchLog :
366|        if (value == 0) return 0;
367|        CLAMPCHECK(value, ZSTD_SEARCHLOG_MIN, ZSTD_SEARCHLOG_MAX);
368|        ZSTD_cLevelToCCtxParams(params);
369|        params->cParams.searchLog = value;
370|        return 0;
371|
372|    case ZSTD_p_minMatch :
373|        if (value == 0) return 0;
374|        CLAMPCHECK(value, ZSTD_SEARCHLENGTH_MIN, ZSTD_SEARCHLENGTH_MAX);
375|        ZSTD_cLevelToCCtxParams(params);
376|        params->cParams.searchLength = value;
377|        return 0;
378|
379|    case ZSTD_p_targetLength :
380|        if (value == 0) return 0;
381|        CLAMPCHECK(value, ZSTD_TARGETLENGTH_MIN, ZSTD_TARGETLENGTH_MAX);
382|        ZSTD_cLevelToCCtxParams(params);
383|        params->cParams.targetLength = value;
384|        return 0;
385|
386|    case ZSTD_p_compressionStrategy :
387|        if (value == 0) return 0;
388|        CLAMPCHECK(value, (unsigned)ZSTD_fast, (unsigned)ZSTD_btultra);
389|        ZSTD_cLevelToCCtxParams(params);
390|        params->cParams.strategy = (ZSTD_strategy)value;
391|        return 0;
392|
393|    case ZSTD_p_contentSizeFlag :
394|        /* Content size written in frame header _when known_ (default:1) */
395|        DEBUGLOG(5, "set content size flag = %u", (value>0));
396|        params->fParams.contentSizeFlag = value > 0;
397|        return 0;
398|
399|    case ZSTD_p_checksumFlag :
400|        /* A 32-bits content checksum will be calculated and written at end of frame (default:0) */
401|        params->fParams.checksumFlag = value > 0;
402|        return 0;
403|
404|    case ZSTD_p_dictIDFlag : /* When applicable, dictionary's dictID is provided in frame header (default:1) */
405|        DEBUGLOG(5, "set dictIDFlag = %u", (value>0));
406|        params->fParams.noDictIDFlag = (value == 0);
407|        return 0;
408|
409|    case ZSTD_p_forceMaxWindow :
410|        params->forceWindow = value > 0;
411|        return 0;
412|
413|    case ZSTD_p_nbThreads :
414|        if (value == 0) return 0;
415|#ifndef ZSTD_MULTITHREAD
416|        if (value > 1) return ERROR(parameter_unsupported);
417|        return 0;
418|#else
419|        return ZSTDMT_initializeCCtxParameters(params, value);
420|#endif
421|
422|    case ZSTD_p_jobSize :
423|#ifndef ZSTD_MULTITHREAD
424|        return ERROR(parameter_unsupported);
425|#else
426|        if (params->nbThreads <= 1) return ERROR(parameter_unsupported);
427|        return ZSTDMT_CCtxParam_setMTCtxParameter(params, ZSTDMT_p_sectionSize, value);
428|#endif
429|
430|    case ZSTD_p_overlapSizeLog :
431|#ifndef ZSTD_MULTITHREAD
432|        return ERROR(parameter_unsupported);
433|#else
434|        if (params->nbThreads <= 1) return ERROR(parameter_unsupported);
435|        return ZSTDMT_CCtxParam_setMTCtxParameter(params, ZSTDMT_p_overlapSectionLog, value);
436|#endif
437|
438|    case ZSTD_p_enableLongDistanceMatching :
439|        if (value != 0) {
440|            ZSTD_cLevelToCCtxParams(params);
441|            params->cParams.windowLog = ZSTD_LDM_DEFAULT_WINDOW_LOG;
442|        }
443|        return ZSTD_ldm_initializeParameters(&params->ldmParams, value);
444|
445|    case ZSTD_p_ldmHashLog :
446|        if (value == 0) return 0;
447|        CLAMPCHECK(value, ZSTD_HASHLOG_MIN, ZSTD_HASHLOG_MAX);
448|        params->ldmParams.hashLog = value;
449|        return 0;
450|
451|    case ZSTD_p_ldmMinMatch :
452|        if (value == 0) return 0;
453|        CLAMPCHECK(value, ZSTD_LDM_MINMATCH_MIN, ZSTD_LDM_MINMATCH_MAX);
454|        params->ldmParams.minMatchLength = value;
455|        return 0;
456|
457|    case ZSTD_p_ldmBucketSizeLog :
458|        if (value > ZSTD_LDM_BUCKETSIZELOG_MAX) {
459|            return ERROR(parameter_outOfBound);
460|        }
461|        params->ldmParams.bucketSizeLog = value;
462|        return 0;
463|
464|    case ZSTD_p_ldmHashEveryLog :
465|        if (value > ZSTD_WINDOWLOG_MAX - ZSTD_HASHLOG_MIN) {
466|            return ERROR(parameter_outOfBound);
467|        }
468|        params->ldmParams.hashEveryLog = value;
469|        return 0;
470|
471|    default: return ERROR(parameter_unsupported);
472|    }
473|}

647|ZSTD_compressionParameters ZSTD_adjustCParams_internal(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
648|{
649|    assert(ZSTD_checkCParams(cPar)==0);
650|    if (srcSize+dictSize == 0) return cPar;   /* no size information available : no adjustment */
651|
652|    /* resize params, to use less memory when necessary */
653|    {   U32 const minSrcSize = (srcSize==0) ? 500 : 0;
654|        U64 const rSize = srcSize + dictSize + minSrcSize;
655|        if (rSize < ((U64)1<<ZSTD_WINDOWLOG_MAX)) {
656|            U32 const srcLog =
657|                    MAX(ZSTD_HASHLOG_MIN, (rSize==1) ? 1 : ZSTD_highbit32((U32)(rSize)-1) + 1);
658|            if (cPar.windowLog > srcLog) cPar.windowLog = srcLog;
659|    }   }
660|    if (cPar.hashLog > cPar.windowLog) cPar.hashLog = cPar.windowLog;
661|    {   U32 const cycleLog = ZSTD_cycleLog(cPar.chainLog, cPar.strategy);
662|        if (cycleLog > cPar.windowLog) cPar.chainLog -= (cycleLog - cPar.windowLog);
663|    }
664|
665|    if (cPar.windowLog < ZSTD_WINDOWLOG_ABSOLUTEMIN) cPar.windowLog = ZSTD_WINDOWLOG_ABSOLUTEMIN;  /* required for frame header */
666|
667|    return cPar;
668|}

670|ZSTD_compressionParameters ZSTD_adjustCParams(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
671|{
672|    cPar = ZSTD_clampCParams(cPar);
673|    return ZSTD_adjustCParams_internal(cPar, srcSize, dictSize);
674|}

676|size_t ZSTD_estimateCCtxSize_usingCCtxParams(const ZSTD_CCtx_params* params)
677|{
678|    /* Estimate CCtx size is supported for single-threaded compression only. */
679|    if (params->nbThreads > 1) { return ERROR(GENERIC); }
680|    {   ZSTD_compressionParameters const cParams =
681|                ZSTD_getCParamsFromCCtxParams(*params, 0, 0);
682|        size_t const blockSize = MIN(ZSTD_BLOCKSIZE_MAX, (size_t)1 << cParams.windowLog);
683|        U32    const divider = (cParams.searchLength==3) ? 3 : 4;
684|        size_t const maxNbSeq = blockSize / divider;
685|        size_t const tokenSpace = blockSize + 11*maxNbSeq;
686|        size_t const chainSize =
687|                (cParams.strategy == ZSTD_fast) ? 0 : ((size_t)1 << cParams.chainLog);
688|        size_t const hSize = ((size_t)1) << cParams.hashLog;
689|        U32    const hashLog3 = (cParams.searchLength>3) ?
690|                                0 : MIN(ZSTD_HASHLOG3_MAX, cParams.windowLog);
691|        size_t const h3Size = ((size_t)1) << hashLog3;
692|        size_t const entropySpace = sizeof(ZSTD_entropyCTables_t);
693|        size_t const tableSpace = (chainSize + hSize + h3Size) * sizeof(U32);
694|
695|        size_t const optBudget =
696|                ((MaxML+1) + (MaxLL+1) + (MaxOff+1) + (1<<Litbits))*sizeof(U32)
697|                + (ZSTD_OPT_NUM+1)*(sizeof(ZSTD_match_t) + sizeof(ZSTD_optimal_t));
698|        size_t const optSpace = ((cParams.strategy == ZSTD_btopt) || (cParams.strategy == ZSTD_btultra)) ? optBudget : 0;
699|
700|        size_t const ldmSpace = params->ldmParams.enableLdm ?
701|            ZSTD_ldm_getTableSize(params->ldmParams.hashLog,
702|                                  params->ldmParams.bucketSizeLog) : 0;
703|
704|        size_t const neededSpace = entropySpace + tableSpace + tokenSpace +
705|                                   optSpace + ldmSpace;
706|
707|        DEBUGLOG(5, "sizeof(ZSTD_CCtx) : %u", (U32)sizeof(ZSTD_CCtx));
708|        DEBUGLOG(5, "estimate workSpace : %u", (U32)neededSpace);
709|        return sizeof(ZSTD_CCtx) + neededSpace;
710|    }
711|}

