725|size_t ZSTD_estimateCStreamSize_usingCCtxParams(const ZSTD_CCtx_params* params)
726|{
727|    if (params->nbThreads > 1) { return ERROR(GENERIC); }
728|    {   size_t const CCtxSize = ZSTD_estimateCCtxSize_usingCCtxParams(params);
729|        size_t const blockSize = MIN(ZSTD_BLOCKSIZE_MAX, (size_t)1 << params->cParams.windowLog);
730|        size_t const inBuffSize = ((size_t)1 << params->cParams.windowLog) + blockSize;
731|        size_t const outBuffSize = ZSTD_compressBound(blockSize) + 1;
732|        size_t const streamingSize = inBuffSize + outBuffSize;
733|
734|        return CCtxSize + streamingSize;
735|    }
