749|static U32 ZSTD_equivalentCParams(ZSTD_compressionParameters cParams1,
750|                                  ZSTD_compressionParameters cParams2)
751|{
752|    U32 bslog1 = MIN(cParams1.windowLog, ZSTD_BLOCKSIZELOG_MAX);
753|    U32 bslog2 = MIN(cParams2.windowLog, ZSTD_BLOCKSIZELOG_MAX);
754|    return (bslog1 == bslog2)   /* same block size */
755|         & (cParams1.hashLog  == cParams2.hashLog)
756|         & (cParams1.chainLog == cParams2.chainLog)
757|         & (cParams1.strategy == cParams2.strategy)   /* opt parser space */
758|         & ((cParams1.searchLength==3) == (cParams2.searchLength==3));  /* hashlog3 space */
759|}

763|static U32 ZSTD_equivalentLdmParams(ldmParams_t ldmParams1,
764|                                    ldmParams_t ldmParams2)
765|{
766|    return (!ldmParams1.enableLdm && !ldmParams2.enableLdm) ||
767|           (ldmParams1.enableLdm == ldmParams2.enableLdm &&
768|            ldmParams1.hashLog == ldmParams2.hashLog &&
769|            ldmParams1.bucketSizeLog == ldmParams2.bucketSizeLog &&
770|            ldmParams1.minMatchLength == ldmParams2.minMatchLength &&
771|            ldmParams1.hashEveryLog == ldmParams2.hashEveryLog);
772|}

775|static U32 ZSTD_equivalentParams(ZSTD_CCtx_params params1,
776|                                 ZSTD_CCtx_params params2)
777|{
778|    return ZSTD_equivalentCParams(params1.cParams, params2.cParams) &&
779|           ZSTD_equivalentLdmParams(params1.ldmParams, params2.ldmParams);
780|}

1601|static size_t ZSTD_compress_frameChunk (ZSTD_CCtx* cctx,
1602|                                     void* dst, size_t dstCapacity,
1603|                               const void* src, size_t srcSize,
1604|                                     U32 lastFrameChunk)
1605|{
1606|    size_t blockSize = cctx->blockSize;
1607|    size_t remaining = srcSize;
1608|    const BYTE* ip = (const BYTE*)src;
1609|    BYTE* const ostart = (BYTE*)dst;
1610|    BYTE* op = ostart;
1611|    U32 const maxDist = (U32)1 << cctx->appliedParams.cParams.windowLog;
1612|
1613|    if (cctx->appliedParams.fParams.checksumFlag && srcSize)
1614|        XXH64_update(&cctx->xxhState, src, srcSize);
1615|
1616|    while (remaining) {
1617|        U32 const lastBlock = lastFrameChunk & (blockSize >= remaining);
1618|        size_t cSize;
1619|
1620|        if (dstCapacity < ZSTD_blockHeaderSize + MIN_CBLOCK_SIZE)
1621|            return ERROR(dstSize_tooSmall);   /* not enough space to store compressed block */
1622|        if (remaining < blockSize) blockSize = remaining;
1623|
1624|        /* preemptive overflow correction:
1625|         * 1. correction is large enough:
1626|         *    lowLimit > (3<<29) ==> current > 3<<29 + 1<<windowLog - blockSize
1627|         *    1<<windowLog <= newCurrent < 1<<chainLog + 1<<windowLog
1628|         *
1629|         *    current - newCurrent
1630|         *    > (3<<29 + 1<<windowLog - blockSize) - (1<<windowLog + 1<<chainLog)
1631|         *    > (3<<29 - blockSize) - (1<<chainLog)
1632|         *    > (3<<29 - blockSize) - (1<<30)             (NOTE: chainLog <= 30)
1633|         *    > 1<<29 - 1<<17
1634|         *
1635|         * 2. (ip+blockSize - cctx->base) doesn't overflow:
1636|         *    In 32 bit mode we limit windowLog to 30 so we don't get
1637|         *    differences larger than 1<<31-1.
1638|         * 3. cctx->lowLimit < 1<<32:
1639|         *    windowLog <= 31 ==> 3<<29 + 1<<windowLog < 7<<29 < 1<<32.
1640|         */
1641|        if (cctx->lowLimit > (3U<<29)) {
1642|            U32 const cycleMask = ((U32)1 << ZSTD_cycleLog(cctx->appliedParams.cParams.chainLog, cctx->appliedParams.cParams.strategy)) - 1;
1643|            U32 const current = (U32)(ip - cctx->base);
1644|            U32 const newCurrent = (current & cycleMask) + ((U32)1 << cctx->appliedParams.cParams.windowLog);
1645|            U32 const correction = current - newCurrent;
1646|            ZSTD_STATIC_ASSERT(ZSTD_CHAINLOG_MAX <= 30);
1647|            ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX_32 <= 30);
1648|            ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX <= 31);
1649|            assert(current > newCurrent);
1650|            assert(correction > 1<<28); /* Loose bound, should be about 1<<29 */
1651|            ZSTD_reduceIndex(cctx, correction);
1652|            cctx->base += correction;
1653|            cctx->dictBase += correction;
1654|            cctx->lowLimit -= correction;
1655|            cctx->dictLimit -= correction;
1656|            if (cctx->nextToUpdate < correction) cctx->nextToUpdate = 0;
1657|            else cctx->nextToUpdate -= correction;
1658|            DEBUGLOG(4, "Correction of 0x%x bytes to lowLimit=0x%x\n", correction, cctx->lowLimit);
1659|        }
1660|
1661|        if ((U32)(ip+blockSize - cctx->base) > cctx->loadedDictEnd + maxDist) {
1662|            /* enforce maxDist */
1663|            U32 const newLowLimit = (U32)(ip+blockSize - cctx->base) - maxDist;
1664|            if (cctx->lowLimit < newLowLimit) cctx->lowLimit = newLowLimit;
1665|            if (cctx->dictLimit < cctx->lowLimit) cctx->dictLimit = cctx->lowLimit;
1666|        }
1667|
1668|        cSize = ZSTD_compressBlock_internal(cctx, op+ZSTD_blockHeaderSize, dstCapacity-ZSTD_blockHeaderSize, ip, blockSize);
1669|        if (ZSTD_isError(cSize)) return cSize;
1670|
1671|        if (cSize == 0) {  /* block is not compressible */
1672|            U32 const cBlockHeader24 = lastBlock + (((U32)bt_raw)<<1) + (U32)(blockSize << 3);
1673|            if (blockSize + ZSTD_blockHeaderSize > dstCapacity) return ERROR(dstSize_tooSmall);
1674|            MEM_writeLE32(op, cBlockHeader24);   /* no pb, 4th byte will be overwritten */
1675|            memcpy(op + ZSTD_blockHeaderSize, ip, blockSize);
1676|            cSize = ZSTD_blockHeaderSize+blockSize;
1677|        } else {
1678|            U32 const cBlockHeader24 = lastBlock + (((U32)bt_compressed)<<1) + (U32)(cSize << 3);
1679|            MEM_writeLE24(op, cBlockHeader24);
1680|            cSize += ZSTD_blockHeaderSize;
1681|        }
1682|
1683|        remaining -= blockSize;
1684|        dstCapacity -= cSize;
1685|        ip += blockSize;
1686|        op += cSize;
1687|    }
1688|
1689|    if (lastFrameChunk && (op>ostart)) cctx->stage = ZSTDcs_ending;
1690|    return op-ostart;
1691|}

1694|static size_t ZSTD_writeFrameHeader(void* dst, size_t dstCapacity,
1695|                                    ZSTD_CCtx_params params, U64 pledgedSrcSize, U32 dictID)
1696|{   BYTE* const op = (BYTE*)dst;
