1698|    U32   const dictIDSizeCode = params.fParams.noDictIDFlag ? 0 : dictIDSizeCodeLength;   /* 0-3 */
1699|    U32   const checksumFlag = params.fParams.checksumFlag>0;
1700|    U32   const windowSize = (U32)1 << params.cParams.windowLog;
1701|    U32   const singleSegment = params.fParams.contentSizeFlag && (windowSize >= pledgedSrcSize);
1702|    BYTE  const windowLogByte = (BYTE)((params.cParams.windowLog - ZSTD_WINDOWLOG_ABSOLUTEMIN) << 3);
1703|    U32   const fcsCode = params.fParams.contentSizeFlag ?
1704|                     (pledgedSrcSize>=256) + (pledgedSrcSize>=65536+256) + (pledgedSrcSize>=0xFFFFFFFFU) : 0;  /* 0-3 */
1705|    BYTE  const frameHeaderDecriptionByte = (BYTE)(dictIDSizeCode + (checksumFlag<<2) + (singleSegment<<5) + (fcsCode<<6) );
1706|    size_t pos=0;
1707|
1708|    if (dstCapacity < ZSTD_frameHeaderSize_max) return ERROR(dstSize_tooSmall);
1709|    DEBUGLOG(4, "ZSTD_writeFrameHeader : dictIDFlag : %u ; dictID : %u ; dictIDSizeCode : %u",
1710|                !params.fParams.noDictIDFlag, dictID,  dictIDSizeCode);
1711|
1712|    if (params.format == ZSTD_f_zstd1) {
1713|        DEBUGLOG(4, "writing zstd magic number");
1714|        MEM_writeLE32(dst, ZSTD_MAGICNUMBER);
1715|        pos = 4;
1716|    }
1717|    op[pos++] = frameHeaderDecriptionByte;
1718|    if (!singleSegment) op[pos++] = windowLogByte;
1719|    switch(dictIDSizeCode)
1720|    {
1721|        default:  assert(0); /* impossible */
