1097|        if (seg0SizeT > bufferSizeT) seg0SizeT = bufferSizeT;
1098|        bufferSizeT -= seg0SizeT;
1099|        for (nb0T=0; (nb0T < seg0SizeT) && (ptrT[nb0T] == 0); nb0T++) ;
1100|        storedSkips += (unsigned)(nb0T * sizeof(size_t));
1101|
1102|        if (nb0T != seg0SizeT) {   /* not all 0s */
1103|            int const seekResult = LONG_SEEK(file, storedSkips, SEEK_CUR);
1104|            if (seekResult) EXM_THROW(72, "Sparse skip error ; try --no-sparse");
1105|            storedSkips = 0;
1106|            seg0SizeT -= nb0T;
1107|            ptrT += nb0T;
1108|            {   size_t const sizeCheck = fwrite(ptrT, sizeof(size_t), seg0SizeT, file);
1109|                if (sizeCheck != seg0SizeT)
1110|                    EXM_THROW(73, "Write error : cannot write decoded block");
1111|        }   }
1112|        ptrT += seg0SizeT;
1113|    }
1114|
1115|    {   static size_t const maskT = sizeof(size_t)-1;
1116|        if (bufferSize & maskT) {
1117|            /* size not multiple of sizeof(size_t) : implies end of block */
1118|            const char* const restStart = (const char*)bufferTEnd;
1119|            const char* restPtr = restStart;
1120|            size_t restSize =  bufferSize & maskT;
1121|            const char* const restEnd = restStart + restSize;
1122|            for ( ; (restPtr < restEnd) && (*restPtr == 0); restPtr++) ;
1123|            storedSkips += (unsigned) (restPtr - restStart);
1124|            if (restPtr != restEnd) {
1125|                int seekResult = LONG_SEEK(file, storedSkips, SEEK_CUR);
1126|                if (seekResult)
1127|                    EXM_THROW(74, "Sparse skip error ; try --no-sparse");
1128|                storedSkips = 0;
1129|                {   size_t const sizeCheck = fwrite(restPtr, 1, restEnd - restPtr, file);
1130|                    if (sizeCheck != (size_t)(restEnd - restPtr))
1131|                        EXM_THROW(75, "Write error : cannot write decoded end of block");
1132|    }   }   }   }
1133|
